script:
frappe.ui.form.on("Purchase Order", {
    first_number: function(frm) {
        calculate_total(frm);
    },

    second_number: function(frm) {
        calculate_total(frm);
    }
});

function calculate_total(frm) {
    let first = flt(frm.doc.first_number);
    let second = flt(frm.doc.second_number);

    frm.set_value("totalke", first + second);
}
